exercises.solution:
import * as fs from "fs";
const lines = fs.readFileSync(0, "utf8").trim().split("\n");
const rows = lines
  .map((l) => l.trim())
  .filter((l) => l.length > 0)
  .map((l) => l.split(","));
const ranked = rows.sort((a, b) => Number(b[1]) - Number(a[1])).slice(0, 3);
const out = ranked.map((r, i) => `${i + 1}. ${r[0]} (${r[1]})`);
console.log(out.join("\n"));

