exercise.solution:
import * as fs from "fs";
const nums = fs.readFileSync(0, "utf8").trim().split(" ").map(Number);
let total = 0;
for (const x of nums) {
  total += x;
}
const desc = [...nums].sort((a, b) => b - a);
console.log(`Count:    ${nums.length}`);
console.log(`Total:    $${total.toFixed(2)}`);
console.log(`Average:  $${(total / nums.length).toFixed(2)}`);
console.log(`Largest:  $${desc[0]!.toFixed(2)}`);
console.log(`Smallest: $${desc[desc.length - 1]!.toFixed(2)}`);
console.log(`Top 3:    ${desc.slice(0, 3).join(", ")}`);

