exercise.solution:
import * as fs from "fs";
type Event =
  | { kind: "add"; desc: string; amount: number }
  | { kind: "remove"; desc: string }
  | { kind: "note"; text: string };
function parse(line: string): Event {
  const p = line.trim().split(" ");
  if (p[0] === "add") return { kind: "add", desc: p[1], amount: Number(p[2]) };
  if (p[0] === "remove") return { kind: "remove", desc: p[1] };
  return { kind: "note", text: p.slice(1).join(" ") };
}
const events: Event[] = fs.readFileSync(0, "utf8").trim().split("\n").map(parse);
const prices: { [key: string]: number } = {};
let added = 0;
let notes = 0;
let balance = 0;
const removed: string[] = [];
for (const e of events) {
  switch (e.kind) {
    case "add":
      added++;
      balance += e.amount;
      prices[e.desc] = e.amount;
      break;
    case "remove":
      removed.push(e.desc);
      balance -= prices[e.desc] ?? 0;
      break;
    case "note":
      notes++;
      break;
  }
}
let addedTotal = 0;
for (const e of events) {
  if (e.kind === "add") addedTotal += e.amount;
}
console.log(`Events:  ${events.length}`);
console.log(`Added:   ${added} ($${addedTotal.toFixed(2)})`);
console.log(`Removed: ${removed.length} (${removed.join(", ")})`);
console.log(`Notes:   ${notes}`);
console.log(`Balance: $${balance.toFixed(2)}`);

