import * as fs from "fs";
interface Sale {
  region: string;
  amount: number;
}
function countBy<T>(xs: T[], key: (x: T) => string): { [k: string]: number } {
  const out: { [k: string]: number } = {};
  for (const x of xs) {
    const k = key(x);
    out[k] = (out[k] ?? 0) + 1;
  }
  return out;
}
function maxBy<T>(xs: T[], score: (x: T) => number): T {
  let best = xs[0];
  for (const x of xs) {
    if (score(x) > score(best)) best = x;
  }
  return best;
}
const sales: Sale[] = fs.readFileSync(0, "utf8").trim().split("\n")
  .filter((l) => l.trim().length > 0)
  .map((l) => {
    const parts = l.split(",");
    return { region: parts[0].trim(), amount: Number(parts[1]) };
  });
const counts = countBy(sales, (s) => s.region);
for (const r of Object.keys(counts).sort()) console.log(`${r}: ${counts[r]}`);
const top = maxBy(sales, (s) => s.amount);
console.log(`Top: ${top.region} ${top.amount}`);

