import * as fs from "fs";
interface Expense {
  desc: string;
  amount: number;
  tag: string;
}
function groupBy<T, K extends keyof T>(rows: T[], key: K): { [k: string]: T[] } {
  const out: { [k: string]: T[] } = {};
  for (const r of rows) {
    const k = String(r[key]);
    if (out[k] === undefined) {
      out[k] = [];
    }
    out[k].push(r);
  }
  return out;
}
function maxBy<T, K extends keyof T>(rows: T[], key: K): T {
  let best = rows[0];
  for (const r of rows) {
    if (r[key] > best[key]) {
      best = r;
    }
  }
  return best;
}
function minBy<T, K extends keyof T>(rows: T[], key: K): T {
  let best = rows[0];
  for (const r of rows) {
    if (r[key] < best[key]) {
      best = r;
    }
  }
  return best;
}
function parse(line: string): Expense {
  const p = line.trim().split(" ");
  return { desc: p[0], amount: Number(p[1]), tag: p[2] };
}
const rows: Expense[] = fs.readFileSync(0, "utf8").trim().split("\n").map(parse);
const groups = groupBy(rows, "tag");
const tagParts = Object.keys(groups).sort().map((k) => `${k}=${groups[k].length}`);
console.log(`Rows:     ${rows.length}`);
console.log(`By tag:   ${tagParts.join(", ")}`);
console.log(`Dearest:  ${maxBy(rows, "amount").desc}`);
console.log(`Cheapest: ${minBy(rows, "amount").desc}`);

